 if(visible.length){host.innerHTML=visible.map(f=>{const disabled=inviteExisting.has(f.id),checked=inviteSelected.has(f.id);return `<label class="room-invite-person ${disabled?'is-invited':''} ${checked?'is-selected':''}"><input type="checkbox" data-invite-select="${esc(f.id)}" ${checked?'checked':''} ${disabled?'disabled':''} aria-label="Select ${esc(f.name)}">${avatar(f.profile)}<span class="room-invite-person-copy"><strong>${esc(f.name)}</strong><small>${disabled?'<i class="fa-solid fa-circle-check"></i> Already invited or in this room':`<i class="fa-solid fa-user-check"></i> @${esc(f.username||'SPIKE friend')}`}</small></span><span class="room-invite-friend-tag">${disabled?'Invited':'Friend'}</span></label>`}).join('')}
 else if(inviteFriends.length){host.innerHTML='<div class="room-invite-empty"><span><i class="fa-solid fa-magnifying-glass"></i></span><strong>No friends found</strong><small>Try another name or username.</small></div>'}
 else{host.innerHTML='<div class="room-invite-empty"><span><i class="fa-solid fa-user-group"></i></span><strong>Your SPIKE friends will appear here</strong><small>Add friends on SPIKE, then come back to invite them into this room.</small><a href="friends.html">Open Friends <i class="fa-solid fa-arrow-up-right-from-square"></i></a></div>'}
 const selectable=visible.filter(f=>!inviteExisting.has(f.id)),selectedVisible=selectable.filter(f=>inviteSelected.has(f.id)).length,all=$('inviteSelectAll');
