async function loadRoomGiftFeed(){const host=$('roomGiftFeed');if(!host||!room?.id)return;try{const r=await db.rpc('spike_room_gift_feed',{p_room_id:room.id});if(r.error)throw r.error;const rows=r.data||[];host.innerHTML=rows.length?rows.map(g=>`<div class="room-gift-feed-item"><span class="gift-icon">${esc(g.gift_icon||'🎁')}</span><span><strong>${esc(g.sender_name)}</strong> sent ${esc(g.gift_name)} to <strong>${esc(g.receiver_name)}</strong><small>${esc(formatTime(g.created_at))} · ${Number(g.coin_cost).toLocaleString('en-NG')} SP</small></span></div>`).join(''):'<div class="gift-placeholder">No gifts sent in this room yet.</div>'}catch(e){host.innerHTML=`<div class="gift-placeholder">${esc(e.message||'Recent gifts are unavailable.')}</div>`}}
let giftCelebrationTimer=null;
function rainGiftEmojis(icon){let rain=document.getElementById('spikeGiftEmojiRain');if(!rain){rain=document.createElement('div');rain.id='spikeGiftEmojiRain';rain.className='spike-gift-emoji-rain';rain.setAttribute('aria-hidden','true');document.body.appendChild(rain)}rain.replaceChildren();const symbols=[icon||'🎁','🎉','✨','💛','🎊'];for(let i=0;i<22;i++){const bit=document.createElement('span');bit.className='spike-gift-rain-bit';bit.textContent=symbols[i%symbols.length];bit.style.left=(2+Math.random()*96)+'%';bit.style.setProperty('--gift-delay',(Math.random()*.8)+'s');bit.style.setProperty('--gift-duration',(2.2+Math.random()*1.5)+'s');bit.style.setProperty('--gift-drift',((Math.random()-.5)*150)+'px');bit.style.fontSize=(18+Math.random()*24)+'px';rain.appendChild(bit)}rain.classList.remove('is-raining');void rain.offsetWidth;rain.classList.add('is-raining');clearTimeout(rain._cleanup);rain._cleanup=setTimeout(()=>{rain.classList.remove('is-raining');rain.replaceChildren()},4300)}
function showGiftCelebration(g){const layer=$('giftCelebration');if(!g?.gift_name)return;rainGiftEmojis(g.gift_icon||'🎁');if(!layer)return;const icon=$('giftCelebrationIcon'),title=$('giftCelebrationTitle'),names=$('giftCelebrationNames');if(icon)icon.textContent=g.gift_icon||'🎁';if(title)title.textContent=g.gift_name+' sent!';if(names)names.textContent=(g.sender_name||'A member')+' → '+(g.receiver_name||'a room member');layer.classList.remove('is-showing','gift-celebration-premium','gift-celebration-luxury','gift-celebration-legendary');const cost=Number(g.coin_cost)||0;layer.classList.add(cost>=5000?'gift-celebration-legendary':cost>=1000?'gift-celebration-luxury':cost>=100?'gift-celebration-premium':'gift-celebration-classic');void layer.offsetWidth;layer.hidden=false;layer.classList.add('is-showing');clearTimeout(giftCelebrationTimer);giftCelebrationTimer=setTimeout(()=>{layer.classList.remove('is-showing');layer.hidden=true},2600)}
async function loadGiftCatalog(){const host=$('roomGiftCatalog');if(!host)return;renderGiftRecipients();try{const [gifts,wallet]=await Promise.all([db.from('spike_gifts').select('gift_type,icon,name,coin_cost,active').eq('active',true).order('coin_cost'),db.rpc('spike_wallet_coin_source_summary')]);if(gifts.error)throw gifts.error;if(wallet.error)throw wallet.error;const coins=Number(wallet.data?.total_coins)||0;const paid=Number(wallet.data?.paid_coins)||0;const bonus=Number(wallet.data?.bonus_coins)||0;roomGiftCoinBalance=coins;const balance=$('roomGiftBalance');if(balance)balance.textContent=`SP COIN balance: ${coins.toLocaleString('en-NG')} · Purchased: ${paid.toLocaleString('en-NG')} · Bonus: ${bonus.toLocaleString('en-NG')}`;host.innerHTML=(gifts.data||[]).map(g=>{const cost=Number(g.coin_cost);const enough=coins>=cost;const canSend=room?.status==='live'&&!!$('roomGiftRecipient')?.value&&enough;const tier=cost>=5000?'legendary':cost>=1000?'luxury':cost>=100?'premium':'classic';const tierLabel=tier==='premium'?'SIGNATURE':tier.toUpperCase();return `<article class="gift-item gift-tier-${tier}" data-gift-type="${esc(g.gift_type)}"><span class="gift-tier-label">${tierLabel}</span><span class="gift-icon" aria-hidden="true">${esc(g.icon||'🎁')}</span><strong>${esc(g.name)}</strong><small>${cost.toLocaleString('en-NG')} SP COINS</small><button type="button" data-send-room-gift="${esc(g.gift_type)}" data-gift-cost="${cost}" ${canSend?'':'disabled'}>${enough?'Send gift':'Not enough coins'}</button></article>`}).join('')||'<div class="gift-placeholder">No gifts are available.</div>';if(!host.dataset.giftBound){host.addEventListener('click',e=>{const button=e.target.closest('[data-send-room-gift]');if(button)void sendRoomGift(button.dataset.sendRoomGift,button)});host.dataset.giftBound='1'}if(!roomGiftRecipientBound){$('roomGiftRecipient')?.addEventListener('change',renderGiftRecipients);roomGiftRecipientBound=true}await loadRoomGiftFeed()}catch(e){host.innerHTML=`<div class="gift-placeholder">${esc(e.message||'Gift catalogue unavailable.')}</div>`}}
let roomGiftRecipientBound=false;
let roomGiftCoinBalance=0;
async function sendRoomGift(giftType,button){if(!room?.id||room.status!=='live')return notice('Gifts can only be sent in a live room.','error');const receiverId=$('roomGiftRecipient')?.value;if(!receiverId)return notice('Choose a room participant to receive the gift.','error');if(!button||button.disabled)return;const requestId=button.dataset.requestId||(crypto.randomUUID?crypto.randomUUID():('xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g,c=>{const r=Math.random()*16|0;return(c==='x'?r:(r&3|8)).toString(16)})));button.dataset.requestId=requestId;button.disabled=true;button.textContent='Sending…';try{const r=await db.rpc('spike_send_room_gift',{p_room_id:room.id,p_receiver_id:receiverId,p_gift_type:giftType,p_request_id:requestId});if(r.error)throw r.error;const gift=r.data||{};const senderName=profileName(profile);const receiverName=gift.receiver_name||profileName(roomProfiles.get(receiverId)||{});notice(`${gift.gift_icon||'🎁'} ${gift.gift_name||'Gift'} sent to ${receiverName}. ${Number(gift.coin_cost||0)} SP COINS spent.`,'success');const celebration={reference:gift.reference,gift_type:gift.gift_type,gift_name:gift.gift_name,gift_icon:gift.gift_icon,coin_cost:gift.coin_cost,sender_name:senderName,receiver_name:receiverName};showGiftCelebration(celebration);if(roomChannel)roomChannel.send({type:'broadcast',event:'room_gift',payload:celebration}).catch(()=>{});await Promise.all([loadGiftCatalog(),loadRoomGiftFeed()])}catch(e){notice(e.message||'Could not send this gift. Your SP COINS were not charged unless the transaction completed.', 'error');button.disabled=false;button.textContent='Retry gift'} }
async function submitReport(e){e.preventDefault();const error=$('roomReportError');error.hidden=true;try{const r=await db.rpc('spike_room_report',{p_room_id:room.id,p_reason:$('roomReportReason').value,p_details:$('roomReportDetails').value.trim()});if(r.error)throw r.error;showOverlay('roomReportOverlay',false);notice('Thank you. Your report has been submitted for review.','success')}catch(err){error.textContent=err.message||'Could not submit your report.';error.hidden=false}}
async function syncRoomAfterReconnect(){if(!room||roomReconnectBusy||!navigator.onLine)return;roomReconnectBusy=true;try{const rows=await fetchRoomMessages();const known=new Set(roomMessages.map(m=>m.id));const fresh=rows.filter(m=>!known.has(m.id));if(fresh.length){const profiles=await getProfiles(fresh.map(m=>m.sender_id));profiles.forEach((v,k)=>roomProfiles.set(k,v));roomMessages=[...roomMessages,...fresh].sort((a,b)=>new Date(a.created_at)-new Date(b.created_at)).slice(-120);renderRoomMessages()}await loadRoomReactions();renderRoomMessages(false);await refreshRoomState();await refreshRoomMembers();setStatus('Room connection restored.')}catch(e){setStatus('Trying to restore room updates…',true)}finally{roomReconnectBusy=false}}
function announceTyping(){if(!roomChannel||!room||!navigator.onLine)return;const now=Date.now();if(now-roomLastTypingAt<1200)return;roomLastTypingAt=now;roomChannel.send({type:'broadcast',event:'room_typing',payload:{user_id:me.id,display_name:profileName(profile)}}).catch(()=>{})}
